            if "venv" in str(py_file) or "tests" in str(py_file):
                continue

            with open(py_file) as f:
                content = f.read()

            # Check for generic exception raising
            if 'raise Exception(' in content:
                violations.append(f"{py_file}: raises generic Exception")

            # Check for error dicts returned
            if 'return {"error":' in content or "return {'error':" in content:
                if "adapters/primary" not in str(py_file):  # Adapters can return dicts
                    violations.append(f"{py_file}: returns error dict")

        assert len(violations) == 0, f"Error handling violations:\n" + "\n".join(violations)

    def _get_imports(self, py_file: Path) -> Set[str]:
        """Get all imports from a Python file"""
        imports = set()
        try:
            with open(py_file) as f:
                tree = ast.parse(f.read())

            for node in ast.walk(tree):
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        imports.add(alias.name.split(".")[0])
                elif isinstance(node, ast.ImportFrom):
                    if node.module:
                        imports.add(node.module.split(".")[0])
        except:
            pass

        return imports

    def _find_cycles(self, graph: Dict[str, Set[str]]) -> List[List[str]]:
        """Find cycles in import graph"""
        cycles = []
        visited = set()
        path = []

        def dfs(node):
            if node in path:
                cycle_start = path.index(node)
                cycles.append(path[cycle_start:] + [node])
                return

            if node in visited:
                return

            visited.add(node)
            path.append(node)

            for neighbor in graph.get(node, set()):
                dfs(neighbor)

            path.pop()

        for node in graph:
            dfs(node)

        return cycles

