from typing import Optional, List, Dict, Any

class DomainException(Exception):
    """Base exception for all domain errors"""

    def __init__(self, message: str, details: Optional[Dict[str, Any]] = None):
        self.message = message
        self.details = details or {}
        super().__init__(self.message)

class ValidationException(DomainException):
    """Raised when validation fails"""

    def __init__(self, message: str, errors: List[str]):
        super().__init__(message, {"validation_errors": errors})
        self.validation_errors = errors

class EntityNotFoundException(DomainException):
    """Raised when entity is not found"""

    def __init__(self, entity_id: str, entity_type: Optional[str] = None):
        message = f"Entity {entity_id} not found"
        if entity_type:
            message = f"{entity_type.capitalize()} {entity_id} not found"
        super().__init__(message, {"entity_id": entity_id, "entity_type": entity_type})

class PermissionDeniedException(DomainException):
    """Raised when permission is denied"""

    def __init__(self, action: str, resource: str):
        message = f"Permission denied for action '{action}' on resource '{resource}'"
        super().__init__(message, {"action": action, "resource": resource})

class DatabaseException(DomainException):
    """Raised when database operation fails"""

    def __init__(self, operation: str, details: Optional[str] = None):
        message = f"Database operation '{operation}' failed"
        if details:
            message = f"{message}: {details}"
        super().__init__(message, {"operation": operation})

class ConfigurationException(DomainException):
    """Raised when configuration is invalid"""

    def __init__(self, setting: str, details: Optional[str] = None):
        message = f"Invalid configuration for '{setting}'"
        if details:
            message = f"{message}: {details}"
        super().__init__(message, {"setting": setting})
