from typing import Dict, Any
from fastapi import Request, HTTPException
from fastapi.responses import JSONResponse
from domain.exceptions import (
    DomainException,
    ValidationException,
    EntityNotFoundException,
    PermissionDeniedException,
    DatabaseException
)
import logging

logger = logging.getLogger(__name__)

class ErrorHandler:
    """Centralized error handling for all adapters"""

    @staticmethod
    def handle_domain_exception(exc: DomainException) -> Dict[str, Any]:
        """Handle domain exception"""
        return {
            "success": False,
            "error": exc.message,
            "details": exc.details
        }

    @staticmethod
    def handle_validation_exception(exc: ValidationException) -> Dict[str, Any]:
        """Handle validation exception"""
        return {
            "success": False,
            "error": "Validation failed",
            "validation_errors": exc.validation_errors,
            "details": exc.details
        }

    @staticmethod
    def handle_not_found_exception(exc: EntityNotFoundException) -> Dict[str, Any]:
        """Handle not found exception"""
        return {
            "success": False,
            "error": exc.message,
            "details": exc.details
        }

    @staticmethod
    def handle_permission_exception(exc: PermissionDeniedException) -> Dict[str, Any]:
        """Handle permission exception"""
        return {
            "success": False,
            "error": exc.message,
            "details": exc.details
        }

    @staticmethod
    def handle_generic_exception(exc: Exception) -> Dict[str, Any]:
        """Handle generic exception"""
        logger.error(f"Unexpected error: {str(exc)}", exc_info=True)
        return {
            "success": False,
            "error": "An unexpected error occurred",
            "details": {"type": type(exc).__name__}
        }

    @staticmethod
    def to_http_response(error_dict: Dict[str, Any]) -> JSONResponse:
        """Convert error dict to HTTP response"""
        status_code = 500  # Default

        if "validation_errors" in error_dict:
            status_code = 400
        elif "not found" in error_dict.get("error", "").lower():
            status_code = 404
        elif "permission denied" in error_dict.get("error", "").lower():
            status_code = 403

        return JSONResponse(
            status_code=status_code,
            content=error_dict
        )

# FastAPI exception handlers
async def domain_exception_handler(request: Request, exc: DomainException):
    """FastAPI handler for domain exceptions"""
    if isinstance(exc, ValidationException):
        error_dict = ErrorHandler.handle_validation_exception(exc)
    elif isinstance(exc, EntityNotFoundException):
        error_dict = ErrorHandler.handle_not_found_exception(exc)
    elif isinstance(exc, PermissionDeniedException):
        error_dict = ErrorHandler.handle_permission_exception(exc)
    else:
        error_dict = ErrorHandler.handle_domain_exception(exc)

    return ErrorHandler.to_http_response(error_dict)

async def generic_exception_handler(request: Request, exc: Exception):
    """FastAPI handler for generic exceptions"""
    error_dict = ErrorHandler.handle_generic_exception(exc)
    return ErrorHandler.to_http_response(error_dict)
