from fastapi import APIRouter, HTTPException, Depends
from application.use_cases.entity_crud import (
    CreateEntityUseCase,
    QueryEntityUseCase,
    UpdateEntityUseCase,
    DeleteEntityUseCase,
    CreateEntityRequest
)
from adapters.dependency_injection import get_use_case

router = APIRouter(prefix="/api/entities", tags=["entities"])

@router.post("/")
async def create_entity(
    request: CreateEntityRequest,
    use_case: CreateEntityUseCase = Depends(lambda: get_use_case(CreateEntityUseCase))
):
    """Create entity endpoint - delegates to use case"""
    response = await use_case.execute(request)

    if not response.success:
        raise HTTPException(
            status_code=400,
            detail={
                "error": response.error,
                "validation_errors": response.validation_errors
            }
        )

    return response.entity.to_dict()

@router.get("/")
async def query_entities(
    entity_type: str = None,
    workspace_id: str = None,
    use_case: QueryEntityUseCase = Depends(lambda: get_use_case(QueryEntityUseCase))
):
    """Query entities endpoint - delegates to use case"""
    entities = await use_case.execute(
        entity_type=entity_type,
        workspace_id=workspace_id
    )
    return [e.to_dict() for e in entities]

@router.put("/{entity_id}")
async def update_entity(
    entity_id: str,
    updates: dict,
    use_case: UpdateEntityUseCase = Depends(lambda: get_use_case(UpdateEntityUseCase))
):
    """Update entity endpoint - delegates to use case"""
    response = await use_case.execute(entity_id, updates)

    if not response.success:
        raise HTTPException(
            status_code=400 if response.validation_errors else 404,
            detail={
                "error": response.error,
                "validation_errors": response.validation_errors
            }
        )

    return response.entity.to_dict()

@router.delete("/{entity_id}")
async def delete_entity(
    entity_id: str,
    use_case: DeleteEntityUseCase = Depends(lambda: get_use_case(DeleteEntityUseCase))
):
    """Delete entity endpoint - delegates to use case"""
    response = await use_case.execute(entity_id)

    if not response.success:
        raise HTTPException(status_code=404, detail=response.error)

    return {"success": True}
