    def validate_entity_creation(
        self,
        entity_type: str,
        name: str,
        metadata: Optional[Dict[str, Any]] = None
    ) -> ValidationResult:
        """Validate entity creation request"""
        errors = []

        # Validate entity type
        if entity_type not in self.ENTITY_TYPES:
            errors.append(f"Invalid entity type: {entity_type}")
            return ValidationResult(is_valid=False, errors=errors)

        # Get validation rules
        rules = self.VALIDATION_RULES.get(entity_type, {})

        # Validate name
        if not name or not name.strip():
            errors.append("Name is required")
        else:
            min_length = rules.get("name_min_length", 1)
            max_length = rules.get("name_max_length", 255)

            if len(name) < min_length:
                errors.append(f"Name must be at least {min_length} characters")
            if len(name) > max_length:
                errors.append(f"Name must be at most {max_length} characters")

        # Validate required fields in metadata
        if metadata:
            required_fields = rules.get("required_fields", [])
            for field in required_fields:
                if field not in ["name"] and field not in metadata:
                    errors.append(f"Required field missing: {field}")

        return ValidationResult(
            is_valid=len(errors) == 0,
            errors=errors
        )

    def validate_entity_update(
        self,
        entity: Entity,
        updates: Dict[str, Any]
    ) -> ValidationResult:
        """Validate entity update request"""
        errors = []

        # Validate name if being updated
        if "name" in updates:
